import pickle
import base64
import os
import subprocess
from celery import Celery
from redis import Redis
import logging

logger = logging.getLogger(__name__)

app = Celery('worker', broker='redis://redis:6379/0', backend='redis://redis:6379/1')

app.conf.update(
    task_serializer='json',
    result_serializer='json',
    accept_content=['json', 'pickle'],
    task_always_eager=False,
    worker_prefetch_multiplier=1,
)

class JobPayload:
    """Represents a deserialized job payload from legacy queue format."""
    def __init__(self, task_name, args, kwargs, metadata=None):
        self.task_name = task_name
        self.args = args
        self.kwargs = kwargs
        self.metadata = metadata or {}


def validate_payload_structure(payload):
    """Basic structural validation of deserialized payload."""
    if not hasattr(payload, 'task_name'):
        raise ValueError("Payload missing task_name")
    if not hasattr(payload, 'args'):
        raise ValueError("Payload missing args")
    if not isinstance(payload.task_name, str):
        raise ValueError("task_name must be string")
    allowed_tasks = ['process_report', 'send_notification', 'aggregate_metrics', 'cleanup_temp']
    if payload.task_name not in allowed_tasks:
        raise ValueError(f"Unknown task: {payload.task_name}")
    return True


@app.task(name='worker.process_legacy_job', bind=True, max_retries=3)
def process_legacy_job(self, encoded_payload):
    """Process jobs from legacy system that sends pickle-serialized payloads.

    Legacy system (v2.x) sends base64-encoded pickle payloads via Redis.
    This handler maintains backward compatibility during migration.
    """
    try:
        raw_bytes = base64.b64decode(encoded_payload)
        # Deserialize the legacy payload format
        payload = pickle.loads(raw_bytes)

        # Validate after deserialization
        validate_payload_structure(payload)

        logger.info(f"Processing legacy job: {payload.task_name}")
        return dispatch_task(payload)
    except Exception as exc:
        logger.error(f"Failed to process legacy job: {exc}")
        raise self.retry(exc=exc, countdown=60)


def dispatch_task(payload):
    """Route validated payload to appropriate handler."""
    handlers = {
        'process_report': handle_report,
        'send_notification': handle_notification,
        'aggregate_metrics': handle_metrics,
        'cleanup_temp': handle_cleanup,
    }
    handler = handlers.get(payload.task_name)
    if handler:
        return handler(payload.args, payload.kwargs)
    raise ValueError(f"No handler for {payload.task_name}")


def handle_report(args, kwargs):
    report_id = kwargs.get('report_id')
    output_path = f"/var/lib/worker/reports/{report_id}.pdf"
    # Simulate report generation
    with open(output_path, 'w') as f:
        f.write(f"Report {report_id} generated")
    return {'status': 'complete', 'path': output_path}


def handle_notification(args, kwargs):
    return {'status': 'sent', 'recipient': kwargs.get('email')}


def handle_metrics(args, kwargs):
    return {'status': 'aggregated', 'count': len(args)}


def handle_cleanup(args, kwargs):
    target_dir = '/var/lib/worker/tmp'
    # Only clean files older than 24h in designated temp dir
    subprocess.run(['find', target_dir, '-mtime', '+1', '-delete'], check=True)
    return {'status': 'cleaned'}


@app.task(name='worker.health_check')
def health_check():
    return {'status': 'healthy', 'pid': os.getpid()}
